@router.get("/invoices/{invoice_id}")
def get_invoice(invoice_id: int, user = Depends(current_user)):
    # current_user rejects the request if the JWT is missing or invalid
    invoice = db.query(Invoice).filter(Invoice.id == invoice_id).first()
    if invoice is None:
        raise HTTPException(404)
    return invoice

@router.get("/dashboard")
def dashboard(user = Depends(current_user)):
    key = "dashboard"
    cached = redis.get(key)
    if cached:
        return json.loads(cached)
    data = build_dashboard(user)
    redis.setex(key, 60, json.dumps(data))
    return data

@router.post("/payments")
def create_payment(body: PaymentIn, idem_key: str = Header(...)):
    existing = db.query(Payment).filter(Payment.idem_key == idem_key).first()
    if existing:
        return existing            # replay the original outcome
    payment = Payment(amount=body.amount, idem_key=idem_key)
    db.add(payment)
    db.commit()                    # unique index on idem_key
    charge_card(payment)
    return payment
